SELECT task_sending_id, task_processing_id, ctrl_cmd_sequence_id, request_control_command_id, task_connection_url, task_sending_control_command_param, task_sending_control_command, task_sending_time, task_sending_status, task_receive_result_msg, task_sending_identifier FROM msa_task_sending_info
WHERE 1=1
and task_sending_id = #{taskSendingId}
and task_processing_id = #{taskProcessingId}
and ctrl_cmd_sequence_id = #{ctrlCmdSequenceId}
and request_control_command_id = #{requestControlCommandId}
order by task_sending_id desc

  		SELECT count(*)
		FROM msa_task_sending_info		
  		WHERE 1=1
  			and request_control_command_id = #{requestControlCommandId}
  			and ctrl_cmd_sequence_id = #{ctrlCmdSequenceId}

  		SELECT task_sending_id,
		   	task_processing_id,
		    ctrl_cmd_sequence_id,
		   	request_control_command_id,
		    task_connection_url,
		    task_sending_control_command_param,
		    task_sending_control_command,
		    task_sending_time,
		   	task_sending_status,
		    task_receive_result_msg,
		    task_sending_identifier
		FROM msa_task_sending_info
  		WHERE 1=1

  				and task_sending_id = #{taskSendingId}


  				and task_sending_identifier = #{taskSendingIdentifier}


  				and task_connection_url = #{task_connection_url}


  				and task_sending_control_command = #{taskSendingControlCommand}


