UPDATE msa_task_sending_info
SET
	task_receive_result_time =  NOW(3)

		,task_sending_status = #{taskSendingStatus}


		,task_receive_result_msg = #{taskReceiveResultMsg}

WHERE 
	task_sending_id = #{taskSendingId} 
	AND task_processing_id = #{taskProcessingId} 
	AND ctrl_cmd_sequence_id = #{ctrlCmdSequenceId} 
	AND request_control_command_id = #{requestControlCommandId}
